import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { Crown, Play, Pause, Trophy, AlertTriangle, GripVertical, Undo2, UserRound, HeartPulse, LogOut, Clock3, Menu, Lock, Unlock, Phone, History, Settings2, X, Pencil, Link2, Mail, Share2, ArrowLeft, ArrowUp, ArrowDown, Loader2, RefreshCw } from 'lucide-react';
import RoundTimer, { KotcSoundCheck } from './RoundTimer';
import KotcHostAccessPanel from './KotcHostAccessPanel';
