function commandId(prefix='kotc'){return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;}
function errMsg(error){return error?.response?.data?.error||error?.data?.error||error?.message||'Unexpected KOTC error';}
const RESOLVED=new Set(['completed','retired','abandoned','not_played']);

function HostScrollControls(){
  const [state,setState]=useState({up:false,down:false});
  useEffect(()=>{
    const update=()=>{const root=document.documentElement;const top=window.scrollY||root.scrollTop||0;const max=Math.max(0,root.scrollHeight-window.innerHeight);setState({up:top>80,down:top<max-80});};
    update();window.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update);const id=setInterval(update,1000);return()=>{window.removeEventListener('scroll',update);window.removeEventListener('resize',update);clearInterval(id);};
  },[]);
  if(!state.up&&!state.down)return null;
  return <div className="hidden md:flex fixed right-4 bottom-6 z-[80] flex-col gap-2" data-testid="kotc-scroll-controls">
    <Button variant="secondary" size="icon" className="h-11 w-11 rounded-full shadow-lg border" aria-label="Scroll up" disabled={!state.up} onClick={()=>window.scrollBy({top:-Math.max(320,window.innerHeight*0.72),behavior:'smooth'})}><ArrowUp className="w-5 h-5"/></Button>
    <Button variant="secondary" size="icon" className="h-11 w-11 rounded-full shadow-lg border" aria-label="Scroll down" disabled={!state.down} onClick={()=>window.scrollBy({top:Math.max(320,window.innerHeight*0.72),behavior:'smooth'})}><ArrowDown className="w-5 h-5"/></Button>
  </div>;
}
function shuffle(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function drawOrderFromRanking(rankedIds,benchIds,courts,method){const bench=new Set(benchIds);const active=rankedIds.filter(id=>!bench.has(id));if(method==='pure_random')return [...shuffle(active),...benchIds];if(method==='strict')return [...active,...benchIds];const c=Math.max(1,courts);const tiers=[];for(let i=0;i<4;i++)tiers.push(shuffle(active.slice(i*c,(i+1)*c)));const balanced=[];for(let court=0;court<c;court++)for(let tier=0;tier<4;tier++)if(tiers[tier]?.[court])balanced.push(tiers[tier][court]);return [...balanced,...benchIds];}

function ScoreCard({ match, names, session, onSaved, disabled, allowHostTakeover=true, collaborativeScoring=false, testFillKey=0 }){
  const [a,setA]=useState(match.team_a_score ?? '');
  const [b,setB]=useState(match.team_b_score ?? '');
  const [serving,setServing]=useState(match.serving_side_at_horn || '');
  const [saving,setSaving]=useState(false);
  const [editing,setEditing]=useState(false);
  const [failed,setFailed]=useState(false);
  const [localSaved,setLocalSaved]=useState(null);
  const [hostOwnsCourt,setHostOwnsCourt]=useState(false);
  const [claiming,setClaiming]=useState(false);
  const savingRef=useRef(false);
  const effectiveMatch=localSaved&&Number(localSaved.revision||0)>=Number(match.revision||0)?{...match,...localSaved}:match;
  const resolved=RESOLVED.has(effectiveMatch.status);
  useEffect(()=>{setA(match.team_a_score ?? '');setB(match.team_b_score ?? '');setServing(match.serving_side_at_horn||'');setEditing(false);setFailed(false);setHostOwnsCourt(false);if(localSaved&&Number(match.revision||0)>=Number(localSaved.revision||0))setLocalSaved(null);},[match.id,match.revision]);
  useEffect(()=>{if(!testFillKey||resolved||saving||collaborativeScoring)return;const court=Number(match.ladder_court_rank||1);setA('11');setB(String(5+(court%4)));setServing('');setFailed(false);},[testFillKey]);
  const teamA=(effectiveMatch.team_a_participant_ids||[]).map(id=>names[id]||id).join(' & ');
  const teamB=(effectiveMatch.team_b_participant_ids||[]).map(id=>names[id]||id).join(' & ');
  const claimHost=async(forCorrection=false)=>{
    if(!collaborativeScoring){if(forCorrection)setEditing(true);return;}
    if(!allowHostTakeover)return;
    setClaiming(true);setFailed(false);
    try{
      const res=await base44.functions.invoke('kotcCommand',{sessionId:session.id,commandId:commandId('host-score-claim'),commandType:'host_claim_score',matchId:match.id});
      setHostOwnsCourt(true);if(forCorrection)setEditing(true);
      toast.success(res.data?.displacedScorer?`Court ${match.ladder_court_rank}: host took over score entry`:`Court ${match.ladder_court_rank} ready for host score entry`);
    }catch(e){toast.error(errMsg(e));}finally{setClaiming(false);}
  };
  const releaseHost=async()=>{
    if(!collaborativeScoring||!hostOwnsCourt)return true;
    try{await base44.functions.invoke('kotcCommand',{sessionId:session.id,commandId:commandId('host-score-release'),commandType:'host_release_score',matchId:match.id});setHostOwnsCourt(false);return true;}catch(e){toast.error(`Could not release Court ${match.ladder_court_rank}: ${errMsg(e)}`);return false;}
  };
  const cancel=async()=>{if(!(await releaseHost()))return;setA(effectiveMatch.team_a_score??'');setB(effectiveMatch.team_b_score??'');setServing(effectiveMatch.serving_side_at_horn||'');setEditing(false);setFailed(false);};
  const submit=async()=>{if(savingRef.current)return;if(collaborativeScoring&&!hostOwnsCourt){toast.error(`Take control of Court ${match.ladder_court_rank} before entering its score.`);return;}if(session.scoring_mode==='timed'&&a!==''&&b!==''&&Number(a)===Number(b)&&!serving){toast.error('Choose which team was serving at the horn.');return;}savingRef.current=true;setFailed(false);try{setSaving(true);const body={sessionId:session.id,commandId:commandId('score'),commandType:resolved?'correct_match':'complete_match',matchId:match.id,expectedMatchRevision:Number(effectiveMatch.revision||0),teamAScore:Number(a),teamBScore:Number(b),servingSideAtHorn:Number(a)===Number(b)?serving:undefined,reason:resolved?'Host score correction':''};const res=resolved?await base44.functions.invoke('kotcCommand',body):await base44.functions.invoke('saveKotcScore',body);const savedMatch=res.data?.match||{...effectiveMatch,status:'completed',team_a_score:Number(a),team_b_score:Number(b),serving_side_at_horn:Number(a)===Number(b)?serving:undefined,revision:Number(effectiveMatch.revision||0)+1};setLocalSaved(savedMatch);setHostOwnsCourt(false);setEditing(false);setFailed(false);toast.success(resolved?'Correction saved':'Result saved');onSaved?.(savedMatch);}catch(e){
    // A browser/network timeout can happen after Base44 has already committed the score.
    // Reconcile against authoritative state before telling a busy host to retry.
    if(!resolved){try{const check=await onSaved?.();const fresh=(check?.data?.matches||[]).find(m=>m.id===match.id);if(fresh&&RESOLVED.has(fresh.status)&&Number(fresh.team_a_score)===Number(a)&&Number(fresh.team_b_score)===Number(b)){setLocalSaved(fresh);setHostOwnsCourt(false);setFailed(false);setEditing(false);toast.success('Result saved');return;}}catch{}}
    setFailed(true);toast.error(errMsg(e));
  }finally{savingRef.current=false;setSaving(false);}};
  const activeEdit=resolved?editing:(!collaborativeScoring||hostOwnsCourt);
  return <div data-testid={`kotc-score-card-${match.ladder_court_rank}`} className={`glass rounded-xl p-3 sm:p-4 space-y-3 border ${failed?'border-destructive/60':saving||claiming?'border-amber-400/60':resolved&&!editing?'border-green-500/30':'border-border'}`}>
    <div className="flex items-center justify-between"><div className="flex items-center gap-2">{Number(match.ladder_court_rank)===1&&<Crown className="w-4 h-4 text-yellow-400"/>}<span className="font-semibold text-sm">Court {match.ladder_court_rank}</span></div><Badge variant="outline">{claiming?'CLAIMING':hostOwnsCourt?'HOST ENTERING':editing?'EDITING':resolved?'SAVED':session.status==='in_progress'?'LIVE':String(match.status||'').toUpperCase()}</Badge></div>
    <div className="grid grid-cols-[1fr_72px] gap-3 items-center"><div><p className="text-[10px] uppercase text-muted-foreground">Team A</p><p className="text-sm font-medium">{teamA}</p></div><Input data-testid={`kotc-score-${match.ladder_court_rank}-a`} className="h-12 text-center text-lg font-bold border-2" type="text" inputMode="numeric" pattern="[0-9]*" maxLength={2} value={a} disabled={disabled||!activeEdit||saving||claiming} onChange={e=>setA(e.target.value.replace(/\D/g,'').slice(0,2))} /></div>
    <div className="grid grid-cols-[1fr_72px] gap-3 items-center"><div><p className="text-[10px] uppercase text-muted-foreground">Team B</p><p className="text-sm font-medium">{teamB}</p></div><Input data-testid={`kotc-score-${match.ladder_court_rank}-b`} className="h-12 text-center text-lg font-bold border-2" type="text" inputMode="numeric" pattern="[0-9]*" maxLength={2} value={b} disabled={disabled||!activeEdit||saving||claiming} onChange={e=>setB(e.target.value.replace(/\D/g,'').slice(0,2))} /></div>
    {session.scoring_mode==='timed'&&activeEdit&&a!==''&&b!==''&&Number(a)===Number(b)&&<div className="rounded-lg border border-amber-400/30 bg-amber-500/10 p-2"><Label className="text-xs font-semibold">Tie at the horn — who was serving?</Label><Select value={serving} onValueChange={setServing}><SelectTrigger className="mt-1"><SelectValue placeholder="Choose serving team"/></SelectTrigger><SelectContent><SelectItem value="A">Team A</SelectItem><SelectItem value="B">Team B</SelectItem></SelectContent></Select></div>}
    {resolved&&!editing&&<div className="rounded-lg bg-green-500/10 border border-green-500/20 p-2 text-center text-xs font-semibold text-green-500">✓ Saved {effectiveMatch.team_a_score}–{effectiveMatch.team_b_score}</div>}
    {collaborativeScoring&&!resolved&&!hostOwnsCourt&&<div className="rounded-lg border border-primary/20 bg-primary/5 p-2 text-xs text-muted-foreground">A player can score this court, or the host can take control here.</div>}
    {saving&&<div className="rounded-lg border border-amber-400/30 bg-amber-500/10 p-2 text-center text-xs font-semibold">Saving…</div>}
    {failed&&<div className="rounded-lg border border-destructive/30 bg-destructive/10 p-2 text-center text-xs font-semibold text-destructive">Save failed — your score is still on screen. Tap Retry Save.</div>}
    {collaborativeScoring&&!resolved&&!hostOwnsCourt&&<Button data-testid={`kotc-host-score-${match.ladder_court_rank}`} className="w-full min-h-12" variant="outline" onClick={()=>claimHost(false)} disabled={disabled||claiming||!allowHostTakeover}>{claiming?'Taking control…':'Enter Score as Host'}</Button>}
    {!resolved&&(!collaborativeScoring||hostOwnsCourt)&&<div className={collaborativeScoring?'grid grid-cols-2 gap-2':''}><Button data-testid={`kotc-complete-${match.ladder_court_rank}`} className="w-full min-h-12" onClick={submit} disabled={disabled||saving||a===''||b===''||(session.scoring_mode==='timed'&&Number(a)===Number(b)&&!serving)}>{saving?'Saving…':failed?'Retry Save':'Complete Match'}</Button>{collaborativeScoring&&<Button className="min-h-12" variant="outline" onClick={cancel} disabled={saving}><X className="w-4 h-4 mr-1"/>Cancel</Button>}</div>}
    {resolved&&!editing&&<Button className="w-full min-h-10" variant="ghost" onClick={()=>claimHost(true)} disabled={disabled||claiming}><Pencil className="w-4 h-4 mr-2"/>{claiming?'Taking control…':'Edit result'}</Button>}
    {resolved&&editing&&<div className="grid grid-cols-2 gap-2"><Button className="min-h-11" onClick={submit} disabled={disabled||saving||a===''||b===''||(session.scoring_mode==='timed'&&Number(a)===Number(b)&&!serving)}>{saving?'Saving…':'Save Correction'}</Button><Button className="min-h-11" variant="outline" onClick={cancel} disabled={saving}><X className="w-4 h-4 mr-1"/>Cancel</Button></div>}
  </div>;
}
function PlayerStatusControls({participants,onAction,saving,currentRound}){
  const [selected,setSelected]=useState(null);const active=participants.filter(p=>!['withdrawn','replaced','no_show'].includes(p.status));const selectedPlayer=active.find(p=>p.id===selected)||null;const act=async(action)=>{if(!selectedPlayer)return;await onAction(selectedPlayer,action);setSelected(null);};
  return <div className="space-y-3"><div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-2">{active.map(p=><button key={p.id} type="button" data-testid={`kotc-player-${p.id}`} onClick={()=>setSelected(p.id===selected?null:p.id)} className={`rounded-lg border p-3 min-h-12 text-left ${selected===p.id?'border-primary ring-2 ring-primary/30':'border-border'}`}><div className="flex items-center justify-between gap-2"><span className="text-sm font-medium">{p.display_name}</span><Badge variant="outline" className="text-[10px]">{String(p.status||'present').replaceAll('_',' ')}</Badge></div></button>)}</div>{selectedPlayer&&<div className="rounded-xl border p-3 space-y-2"><p className="text-sm font-semibold">{selectedPlayer.display_name}</p><div className="grid grid-cols-1 sm:grid-cols-2 gap-2"><Button data-testid="kotc-player-sit-out" variant="outline" onClick={()=>act('voluntary_rest')} disabled={saving}><Clock3 className="w-4 h-4 mr-1"/>Sit Out 1 Round</Button><Button variant="outline" onClick={()=>act('temporarily_unavailable')} disabled={saving}><UserRound className="w-4 h-4 mr-1"/>Temporarily Unavailable</Button><Button variant="outline" onClick={()=>act('injured')} disabled={saving}><HeartPulse className="w-4 h-4 mr-1"/>Injured</Button><Button variant="outline" onClick={()=>act('leaving_early')} disabled={saving}><LogOut className="w-4 h-4 mr-1"/>Leaving Early</Button><Button className="sm:col-span-2" onClick={()=>act('back_available')} disabled={saving}>Back Available</Button></div><p className="text-[10px] text-muted-foreground">Changes apply safely from the current/next round without rewriting completed history.</p></div>}</div>;
}

function ProposedRoundEditor({round,slots,participants,names,fixedPairs,onStart,onPairLock,onBackToSetup,saving,startError,playMinutes=8}){
  const ordered=useMemo(()=>[...slots].sort((a,b)=>Number(a.ladder_court_rank)-Number(b.ladder_court_rank)||String(a.team_side).localeCompare(String(b.team_side))||Number(a.slot_number)-Number(b.slot_number)),[slots]);
  const original=useMemo(()=>Object.fromEntries(ordered.map(s=>[s.id,String(s.participant_id)])),[ordered]);
  const [draft,setDraft]=useState(original);const [selected,setSelected]=useState(null);const [pairBusyKey,setPairBusyKey]=useState('');const [roundMinutes,setRoundMinutes]=useState(Math.min(60,Math.max(1,Number(playMinutes)||8)));
  useEffect(()=>{setDraft(original);setSelected(null);setPairBusyKey('');setRoundMinutes(Math.min(60,Math.max(1,Number(playMinutes)||8)));},[round?.id,round?.proposal_revision,playMinutes,JSON.stringify(original)]);
  const activeIds=new Set(Object.values(draft));const eligible=participants.filter(p=>['registered','confirmed','present','leaving_early'].includes(p.status));const bench=eligible.filter(p=>!activeIds.has(String(p.id)));
  const swapSlot=(source,target)=>{if(!source||!target||source===target){setSelected(null);return;}setDraft(prev=>({...prev,[source]:prev[target],[target]:prev[source]}));setSelected(null);};
  const clickCourt=id=>{if(!selected){setSelected({type:'court',id});return;}if(selected.type==='court')return swapSlot(selected.id,id);const benchId=selected.id;setDraft(prev=>({...prev,[id]:benchId}));setSelected(null);};
  const clickBench=id=>{if(!selected){setSelected({type:'bench',id});return;}if(selected.type==='bench'){setSelected(selected.id===id?null:{type:'bench',id});return;}const source=selected.id;const outgoing=draft[source];setDraft(prev=>({...prev,[source]:id}));setSelected({type:'bench',id:outgoing});setSelected(null);};
  const courts=[...new Set(ordered.map(s=>Number(s.ladder_court_rank)))];
  const hostLocks=(fixedPairs||[]).filter(p=>p.status==='active'&&p.pair_source==='host_selected');
  const issues=[];const vals=Object.values(draft);if(vals.length!==Number(round.active_court_count||0)*4)issues.push('Every active court needs four players.');if(new Set(vals).size!==vals.length)issues.push('A player appears more than once.');
  for(const rank of courts){const c=ordered.filter(s=>Number(s.ladder_court_rank)===rank);if(c.length!==4)issues.push(`Court ${rank} is incomplete.`);}
  for(const l of hostLocks){const a=String(l.participant1_id),b=String(l.participant2_id);if(vals.includes(a)&&vals.includes(b)){const together=courts.some(rank=>['A','B'].some(side=>ordered.filter(s=>Number(s.ladder_court_rank)===rank&&s.team_side===side).map(s=>draft[s.id]).includes(a)&&ordered.filter(s=>Number(s.ladder_court_rank)===rank&&s.team_side===side).map(s=>draft[s.id]).includes(b)));if(!together)issues.push(`Locked pair ${l.pair_name||''} is split.`);}}
  const lockFor=(ids)=>hostLocks.find(l=>ids.includes(String(l.participant1_id))&&ids.includes(String(l.participant2_id)));
  const pairKey=(ids)=>[...ids].map(String).sort().join('|');
  const togglePair=async(ids,isLocked)=>{const key=pairKey(ids);if(pairBusyKey)return;setPairBusyKey(key);try{await onPairLock(ids,isLocked,draft,round);}finally{setPairBusyKey('');}};
  return <div className="space-y-4" data-testid="kotc-round-editor">
    {bench.length>0&&<div className="rounded-xl border-2 border-amber-400/60 bg-amber-500/10 p-3" data-testid="kotc-bench"><p className="text-[11px] uppercase tracking-wider text-amber-500 font-bold">Bench This Round</p><div className="flex flex-wrap gap-2 mt-2">{bench.map(p=><button key={p.id} data-testid={`kotc-bench-player-${p.id}`} onClick={()=>clickBench(String(p.id))} className={`rounded-lg border px-3 py-2 text-sm font-semibold ${selected?.type==='bench'&&selected.id===String(p.id)?'border-primary ring-2 ring-primary/30':'border-amber-400/30'}`}>{p.display_name}</button>)}</div><p className="text-[10px] text-muted-foreground mt-2">Tap a court player, then a bench player, to swap them.</p></div>}
    <div className="glass rounded-xl p-3 sm:p-4 space-y-4"><div><h4 className="font-semibold text-sm">Host Round Editor</h4><p className="text-xs text-muted-foreground mt-1">Tap one player then another to swap. Only one pending selection is allowed.</p></div><div className="grid lg:grid-cols-2 gap-4">{courts.map(rank=><div key={rank} className="rounded-xl border p-3 space-y-3"><div className="flex items-center gap-2">{rank===1&&<Crown className="w-4 h-4 text-yellow-400"/>}<span className="font-semibold text-sm">Court {rank}</span></div>{['A','B'].map(side=>{const teamSlots=ordered.filter(s=>Number(s.ladder_court_rank)===rank&&s.team_side===side).sort((a,b)=>Number(a.slot_number)-Number(b.slot_number));const ids=teamSlots.map(s=>draft[s.id]);const lock=lockFor(ids);return <div key={side}><div className="flex items-center justify-between mb-1"><p className="text-[10px] uppercase text-muted-foreground">Team {side}</p>{ids.length===2&&<Button variant="ghost" size="sm" className={`h-7 px-2 text-[10px] ${pairBusyKey===pairKey(ids)?'bg-primary/10 text-primary':''}`} onClick={()=>togglePair(ids,!!lock)} disabled={saving||!!pairBusyKey}>{pairBusyKey===pairKey(ids)?<>Saving…</>:lock?<><Unlock className="w-3 h-3 mr-1"/>Locked ✓ · Unlock</>:<><Lock className="w-3 h-3 mr-1"/>Lock pair</>}</Button>}</div><div className="grid grid-cols-2 gap-2">{teamSlots.map(slot=>{const pid=draft[slot.id]||slot.participant_id;const isSelected=selected?.type==='court'&&selected.id===slot.id;return <button key={slot.id} type="button" data-testid={`kotc-slot-${slot.id}`} onClick={()=>clickCourt(slot.id)} className={`rounded-lg border p-3 text-left min-h-[58px] flex items-center gap-2 touch-manipulation ${isSelected?'border-primary ring-2 ring-primary/30':'border-border'}`}><GripVertical className="w-4 h-4 shrink-0 text-muted-foreground"/><span className="text-sm font-medium leading-tight">{names[pid]||pid}</span></button>;})}</div></div>;})}</div>)}</div></div>
    {issues.length>0&&<div className="rounded-xl border border-destructive/40 bg-destructive/10 p-3 text-sm"><p className="font-semibold text-destructive mb-1">Round not ready</p>{issues.map((x,i)=><p key={i} className="text-xs text-destructive">• {x}</p>)}</div>}
    <div className="rounded-2xl border-2 border-primary/30 bg-primary/5 p-3 sm:p-4 space-y-3" data-testid="kotc-pre-round-check">
      <div><p className="text-[10px] uppercase tracking-[.18em] text-primary font-bold">Pre-Round Check</p><p className="text-xs text-muted-foreground mt-1">Confirm the round time and hall sound before players begin.</p></div>
      <div className="rounded-xl border bg-background/70 p-3">
        <div className="flex items-center justify-between gap-3"><div className="flex items-center gap-2"><Clock3 className="w-4 h-4 text-primary"/><div><p className="text-xs font-bold">Round timer</p><p className="text-[10px] text-muted-foreground">Adjust now if tonight needs a shorter or longer round.</p></div></div><div data-testid="kotc-prestart-timer-value" className="font-mono text-2xl font-black tabular-nums">{String(roundMinutes).padStart(2,'0')}:00</div></div>
        <div className="grid grid-cols-2 gap-2 mt-3"><Button type="button" variant="outline" className="min-h-11" onClick={()=>setRoundMinutes(v=>Math.max(1,v-1))} disabled={saving||roundMinutes<=1}>− 1 min</Button><Button type="button" variant="outline" className="min-h-11" onClick={()=>setRoundMinutes(v=>Math.min(60,v+1))} disabled={saving||roundMinutes>=60}>+ 1 min</Button></div>
      </div>
      <KotcSoundCheck />
      <Button data-testid="kotc-start-round" className="w-full min-h-14 text-base font-bold" onClick={()=>onStart(draft,roundMinutes)} disabled={saving||issues.length>0}><Play className="w-5 h-5 mr-2"/>{saving?'Starting…':`START ROUND ${round.round_number}`}</Button>
    </div>
    {startError&&<div data-testid="kotc-start-error" className="rounded-xl border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive"><p className="font-semibold">Round did not start</p><p className="text-xs mt-1">{startError}</p><p className="text-xs mt-1">Your draw is still safe. Correct the issue shown above and press Start Round again.</p></div>}
    {Number(round.round_number)===1&&<Button className="w-full" variant="outline" onClick={onBackToSetup} disabled={saving}><ArrowLeft className="w-4 h-4 mr-2"/>Back to Setup</Button>}
    <Button className="w-full" variant="ghost" onClick={()=>{setDraft(original);setSelected(null);}} disabled={saving}><Undo2 className="w-4 h-4 mr-2"/>Restore Original Draw</Button>
  </div>;
}

function standingsFrom(matches,participants){const s=Object.fromEntries(participants.map(p=>[p.id,{id:p.id,name:p.display_name,w:0,l:0,pf:0,pa:0,played:0,c1:0}]));for(const m of matches.filter(m=>m.status==='completed')){for(const id of [...(m.team_a_participant_ids||[]),...(m.team_b_participant_ids||[])])if(s[id]){s[id].played++;if(Number(m.ladder_court_rank)===1)s[id].c1++;}for(const id of m.team_a_participant_ids||[])if(s[id]){s[id].pf+=Number(m.team_a_score||0);s[id].pa+=Number(m.team_b_score||0);m.winner_side==='A'?s[id].w++:s[id].l++;}for(const id of m.team_b_participant_ids||[])if(s[id]){s[id].pf+=Number(m.team_b_score||0);s[id].pa+=Number(m.team_a_score||0);m.winner_side==='B'?s[id].w++:s[id].l++;}}return Object.values(s).sort((a,b)=>b.w-a.w||(b.pf-b.pa)-(a.pf-a.pa)||b.c1-a.c1||a.name.localeCompare(b.name));}

